import{_ as r,M as s,p as d,q as i,R as e,t,N as n,a3 as a}from"./framework-dd056dd6.js";const l={},h=a('<h1 id="assignment-1-blacksmith-—-the-tiny-forge" tabindex="-1"><a class="header-anchor" href="#assignment-1-blacksmith-—-the-tiny-forge" aria-hidden="true">#</a> Assignment 1: Blacksmith — The Tiny Forge</h1><p><strong>Course:</strong> MTM6302 — Web Development with JavaScript<br><strong>Due:</strong> See the assignment deadline in Brightspace.</p><h2 id="your-task" tabindex="-1"><a class="header-anchor" href="#your-task" aria-hidden="true">#</a> Your task</h2><p>Bring a tiny blacksmith’s forge to life using JavaScript. Heat the forge, make swords, and display the results on the page.</p><p>Use the same approach as the monster demo:</p><p><strong>Call an action → check or change the state → update the page.</strong></p><p>Play through commands in the browser console. The web page shows the forge’s current condition and your progress.</p><h2 id="getting-started" tabindex="-1"><a class="header-anchor" href="#getting-started" aria-hidden="true">#</a> Getting started</h2>',8),c={href:"https://github.com/MTM6302-Web-Dev-III/A1-Blacksmith",target:"_blank",rel:"noopener noreferrer"},u=a("<li>Select <strong>Fork</strong> to create a copy in your own GitHub account.</li><li>Clone <strong>your fork</strong>, then open the folder in VS Code.</li><li>Open <code>index.html</code> in your browser and open the console.</li><li>Write your JavaScript in <code>script.js</code>.</li>",4),g=a('<p>Use the assignment’s HTML and CSS starter files. Your assessed work is the JavaScript behaviour; you do not need to redesign the page.</p><h2 id="game-rules" tabindex="-1"><a class="header-anchor" href="#game-rules" aria-hidden="true">#</a> Game rules</h2><p>Track only two changing numbers:</p><table><thead><tr><th>Variable</th><th style="text-align:right;">Starting value</th><th>Rule</th></tr></thead><tbody><tr><td>Forge heat</td><td style="text-align:right;">20</td><td>Stays between 0 and 100.</td></tr><tr><td>Swords made</td><td style="text-align:right;">0</td><td>Increases by one after successful crafting.</td></tr></tbody></table><p>Making one sword requires <strong>at least 30 heat</strong> and uses <strong>30 heat</strong>. You do not need to buy supplies or sell swords.</p><p>The forge’s appearance depends on its heat:</p><table><thead><tr><th>Heat</th><th>Status</th><th>Can you make a sword?</th></tr></thead><tbody><tr><td>Below 30</td><td>Too cold</td><td>No</td></tr><tr><td>30 to below 70</td><td>Ready to forge</td><td>Yes</td></tr><tr><td>70 to 100</td><td>Roaring fire</td><td>Yes</td></tr></tbody></table><p>“Roaring fire” is a visual state, not a restriction on crafting.</p><h2 id="required-functions" tabindex="-1"><a class="header-anchor" href="#required-functions" aria-hidden="true">#</a> Required functions</h2><p>Build these five functions. The first three are the player’s console commands; the last two support the display.</p><h3 id="_1-heatforge-amount" tabindex="-1"><a class="header-anchor" href="#_1-heatforge-amount" aria-hidden="true">#</a> 1. <code>heatForge(amount)</code></h3><ul><li>Add <code>amount</code> to the current heat.</li><li>Stop the heat at 100 if the addition would exceed 100.</li><li>Display a short message confirming that the forge was heated.</li><li>Call <code>updateForge()</code>.</li></ul><p>For this assignment, the player will supply whole-number amounts from 0 to 100. You do not need to handle text, missing arguments, or other invalid inputs.</p><p>Example command: <code>heatForge(20)</code>.</p><h3 id="_2-makesword" tabindex="-1"><a class="header-anchor" href="#_2-makesword" aria-hidden="true">#</a> 2. <code>makeSword()</code></h3><ul><li>If heat is at least 30, subtract 30 heat and add one sword.</li><li>Display a success message when a sword is made.</li><li>Otherwise, leave both numbers unchanged and display a message explaining that more heat is needed.</li><li>Call <code>updateForge()</code> after either result.</li></ul><p>Exactly 30 heat is enough. Each call makes at most one sword.</p><h3 id="_3-resetforge" tabindex="-1"><a class="header-anchor" href="#_3-resetforge" aria-hidden="true">#</a> 3. <code>resetForge()</code></h3><ul><li>Restore heat to 20 and swords made to 0.</li><li>Replace the previous action message with a starting message.</li><li>Call <code>updateForge()</code>.</li></ul><h3 id="_4-getforgestatus-heatvalue" tabindex="-1"><a class="header-anchor" href="#_4-getforgestatus-heatvalue" aria-hidden="true">#</a> 4. <code>getForgeStatus(heatValue)</code></h3><ul><li>Use <code>if / else if / else</code> to choose the status from the table above.</li><li>Return the status as a string.</li><li>Keep this function focused on choosing a value; it should not change the page.</li></ul><h3 id="_5-updateforge" tabindex="-1"><a class="header-anchor" href="#_5-updateforge" aria-hidden="true">#</a> 5. <code>updateForge()</code></h3><ul><li><p>Display the current heat and sword count using <code>textContent</code>.</p></li><li><p>Call <code>getForgeStatus()</code> and display its returned value.</p></li><li><p>Use <code>classList</code> to apply the matching starter CSS class: <code>is-cold</code>, <code>is-ready</code>, or <code>is-roaring</code>.</p></li><li><p>Remove the previous status classes so only one remains.</p></li><li><p>Update the supplied image’s <code>src</code> and <code>alt</code> attributes to match the heat, as in the monster demo:</p><table><thead><tr><th>Status</th><th>Image</th><th>Alternative text</th></tr></thead><tbody><tr><td>Too cold</td><td><code>assets/forge-cold.svg</code></td><td>A stone forge with dark coals and no flames</td></tr><tr><td>Ready to forge</td><td><code>assets/forge-ready.svg</code></td><td>A stone forge with a small orange fire</td></tr><tr><td>Roaring fire</td><td><code>assets/forge-roaring.svg</code></td><td>A stone forge with tall bright flames and sparks</td></tr></tbody></table></li><li><p>Keep the most recent action message visible. Updating the status must not erase a success or failure message.</p></li></ul><p>Call <code>resetForge()</code> once when the script loads so the page starts in the correct state.</p><h2 id="page-requirements" tabindex="-1"><a class="header-anchor" href="#page-requirements" aria-hidden="true">#</a> Page requirements</h2><p>The page must show:</p><ul><li>Current heat, out of 100.</li><li>Number of swords made.</li><li>Forge status as text.</li><li>A short message describing the most recent action.</li><li>A matching forge graphic and visual styling for each status.</li></ul><p>Use text as well as colour to communicate the forge’s status. Use the three supplied graphics; you do not need to create artwork, new HTML elements, or animations.</p><h2 id="plan-your-approach" tabindex="-1"><a class="header-anchor" href="#plan-your-approach" aria-hidden="true">#</a> Plan your approach</h2><p>Before coding, write a few pseudocode comments at the top of <code>script.js</code>. Describe how making a sword will work. Use plain language rather than JavaScript syntax.</p><p>Build in this order:</p><ol><li>Select the existing page elements and create the two state variables.</li><li>Build <code>getForgeStatus()</code> and <code>updateForge()</code>.</li><li>Build <code>resetForge()</code> and call it to initialize the page.</li><li>Build and test <code>heatForge(amount)</code>.</li><li>Build and test both outcomes of <code>makeSword()</code>.</li></ol><p>Refer to the monster demo for the patterns. Adapt them to the forge’s rules and use clear names related to this game.</p><h2 id="test-your-game" tabindex="-1"><a class="header-anchor" href="#test-your-game" aria-hidden="true">#</a> Test your game</h2><p>Run each row independently, starting with <code>resetForge()</code>. Check the numbers, status text, class, image, alternative text, and action message.</p><table><thead><tr><th>Commands after resetting</th><th>Expected result</th></tr></thead><tbody><tr><td>No additional command</td><td>Heat 20; swords 0; Too cold.</td></tr><tr><td><code>makeSword()</code></td><td>Heat 20; swords 0; a message explaining that more heat is needed.</td></tr><tr><td><code>heatForge(9)</code></td><td>Heat 29; swords 0; Too cold.</td></tr><tr><td><code>heatForge(10)</code></td><td>Heat 30; swords 0; Ready to forge.</td></tr><tr><td><code>heatForge(10)</code>, then <code>makeSword()</code></td><td>Heat 0; swords 1; Too cold; success message.</td></tr><tr><td><code>heatForge(49)</code></td><td>Heat 69; swords 0; Ready to forge.</td></tr><tr><td><code>heatForge(50)</code></td><td>Heat 70; swords 0; Roaring fire.</td></tr><tr><td><code>heatForge(100)</code></td><td>Heat capped at 100; swords 0; Roaring fire.</td></tr><tr><td><code>heatForge(100)</code>, then call <code>makeSword()</code> four times</td><td>Three swords are made; the fourth attempt fails. Heat 10; swords 3.</td></tr></tbody></table><p>Finally, call <code>resetForge()</code> after playing. Confirm that the numbers, status, styling, and message return to their starting values.</p><h2 id="scope" tabindex="-1"><a class="header-anchor" href="#scope" aria-hidden="true">#</a> Scope</h2><p>The required game is complete when the functions and tests above work. Buying, selling, gold, wood, ore, axes, inventory commands, and help commands are not required.</p><p>Buttons, event listeners, arrays, custom data objects, loops, timers, storage, and external libraries are not required. You can complete the assignment with the Week 3 concepts used in the monster demo.</p><h2 id="submission" tabindex="-1"><a class="header-anchor" href="#submission" aria-hidden="true">#</a> Submission</h2><ol><li>Test the required behaviours and fix console errors.</li><li>Create a commit with the message <code>Completes the assignment.</code></li><li>Push your work to your fork on GitHub.</li><li>Submit the URL of <strong>your fork</strong> in Brightspace, not the instructor’s starter repository. You do not need to open a pull request.</li></ol><p>Your submission should include the working page, supplied styles, and your JavaScript file. No separate report or video is required.</p><h2 id="assessment-focus" tabindex="-1"><a class="header-anchor" href="#assessment-focus" aria-hidden="true">#</a> Assessment focus</h2><ul><li>Correct state changes and conditions, including the boundary cases.</li><li>Functions with clear responsibilities, including a parameter and a returned value.</li><li>Accurate DOM text, class, and image attribute updates after each action.</li><li>Readable JavaScript and a short pseudocode plan.</li></ul><p>Additional game features are not needed to meet these requirements.</p>',46);function p(m,f){const o=s("ExternalLinkIcon");return d(),i("div",null,[h,e("ol",null,[e("li",null,[t("Open the "),e("a",c,[t("Starter GitHub Repository"),n(o)]),t(" using the link in Brightspace.")]),u]),g])}const y=r(l,[["render",p],["__file","blacksmith.html.vue"]]);export{y as default};
